# -*- coding: utf-8 -*-
from ._helpers import intro, schema, fall, mc

KURS = dict(
    id="u04", gebiet="upc", titel="Verletzung und Auslegung vor dem EPG", untertitel="Art. 69 EPÜ, Art. 25 bis 29 und 63 EPGÜ in der Rechtsprechung des Berufungsgerichts",
    farbe="#7a3e9d", icon="marke",
    beschreibung="Die Begründetheit der Verletzungsklage: Wie das Berufungsgericht den Patentanspruch auslegt (NanoString/10x, Meril/Edwards, Dyson/Dreame, Amgen/Regeneron), was „Anbieten“ und mittelbare Verletzung bedeuten (Belkin/Philips, Lepu/Occlutech, Onward/Niche), wie Äquivalenz geprüft wird, und welche Einwendungen bleiben: Schranken, Vorbenutzung, Erschöpfung, Geschäftsführerhaftung, FRAND.",
    kapitel=[
        dict(id="u04a", titel="Schutzbereich: Auslegung des Patentanspruchs", einheiten=[
            schema("u04a-0", "Prüfungsschema: Verletzungsklage vor dem EPG", "upc_schema_verletzungsklage",
                   "Die Begründetheit beginnt immer mit dem Schutzbereich. Das EPGÜ enthält keine eigene Auslegungsregel; maßgeblich sind Art. 69 EPÜ und das Auslegungsprotokoll, die das Berufungsgericht seit NanoString/10x in einer festen Formel anwendet. Erst danach folgen Benutzungshandlung (Art. 25, 26 EPGÜ), Gebiet und Zustimmung, Einwendungen (Art. 27 bis 29 EPGÜ) und der Rechtsbestand."),
            fall("u04a-1", "Beschreibung nur bei Unklarheit?",
                 "Die NanoString-Gruppe wehrt sich gegen eine einstweilige Anordnung der Lokalkammer München zugunsten von 10x Genomics. Sie meint, der Wortlaut des Anspruchs sei eindeutig; auf die Beschreibung und die Zeichnungen dürfe das Gericht deshalb gar nicht zurückgreifen. 10x hält dem entgegen, dass die Beschreibung ein Merkmal enger fasst als der isolierte Wortlaut.",
                 "Darf das Gericht Beschreibung und Zeichnungen nur heranziehen, wenn der Anspruchswortlaut unklar ist?", False,
                 ["**Nein!** Nach Art. 69 EPÜ und dem Auslegungsprotokoll ist der Patentanspruch nicht nur Ausgangspunkt, sondern **maßgebliche Grundlage** für den Schutzbereich. Beschreibung und Zeichnungen sind aber **stets** als Erläuterungshilfen heranzuziehen, nicht nur bei Unklarheiten des Wortlauts (EPG-BerG NanoString/10x).",
                  "Die Auslegung erfolgt aus Sicht der Fachperson; angemessener Schutz des Patentinhabers und hinreichende Rechtssicherheit für Dritte sind miteinander zu verbinden. Dieselben Grundsätze gelten für die Verletzungsfrage und für den Rechtsbestand, damit das Patent nicht im Verletzungsprozess weit und im Nichtigkeitsverfahren eng gelesen wird."],
                 merke="Anspruch = Grundlage, Beschreibung und Zeichnungen = immer Erläuterungshilfe (NanoString/10x).",
                 level=1, concepts=["upc_auslegung_patentanspruch", "upc_fachperson"], norms=["Art. 25 EPGÜ", "Art. 24 EPGÜ"], cases=["upc_coa_nanostring_10x"], step="step:upc_schema_verletzungsklage.2.1"),
            fall("u04a-2", "Das Ausführungsbeispiel, das nicht passen soll",
                 "Edwards klagt gegen Meril aus einem Patent für eine Herzklappenprothese. Meril argumentiert, ein Merkmal des Hauptanspruchs sei nach seinem Wortlaut so eng zu verstehen, dass das in der Patentschrift beschriebene Ausführungsbeispiel gar nicht unter den Anspruch falle; folglich falle auch die eigene Prothese, die diesem Beispiel entspricht, nicht darunter.",
                 "Ist eine Auslegung, die das Ausführungsbeispiel aus dem Anspruch ausschließt, in der Regel richtig?", False,
                 ["**Nein!** Ein in der Patentschrift beschriebenes Ausführungsbeispiel ist **in der Regel vom Anspruch umfasst**; eine Auslegung, die es ausschließt, kommt nur in Betracht, wenn das Patent eindeutig das Gegenteil lehrt, etwa weil das Beispiel im Erteilungsverfahren erkennbar aus dem Anspruch herausgenommen wurde (EPG-BerG Meril/Edwards).",
                  "Grund ist Art. 69 EPÜ: Die Beschreibung erläutert den Anspruch, und die Fachperson wird ein Merkmal so verstehen, dass die als erfindungsgemäß beschriebene Ausführung darunterfällt. Meril kann sich also nicht mit einer Auslegung verteidigen, die dem Patent sein eigenes Beispiel nimmt."],
                 merke="Ausführungsbeispiel fällt unter den Anspruch, außer das Patent sagt eindeutig etwas anderes (Meril/Edwards).",
                 level=2, concepts=["upc_auslegung_patentanspruch"], norms=["Art. 25 EPGÜ"], cases=["upc_coa_meril_edwards_parteien"], step="step:upc_schema_verletzungsklage.2.1"),
            mc("u04a-3", "Auslegungsregeln des Berufungsgerichts",
               "Welche Aussage zur Auslegung eines Patentanspruchs entspricht der Rechtsprechung des Berufungsgerichts?",
               ["Bei einem Merkmal, das ein Bauteil beschreibt, kommt es allein auf die Funktion des Bauteils an; die im Patent gelehrte räumlich-körperliche Anordnung ist unerheblich",
                "Ein Merkmal ist im Lichte des gesamten Anspruchs auszulegen; identische Begriffe haben grundsätzlich dieselbe Bedeutung, sofern nicht Beschreibung oder Funktion ein abweichendes Verständnis ergeben",
                "Enthält ein Unteranspruch ein zusätzliches Merkmal, folgt daraus zwingend, dass der Hauptanspruch dieses Merkmal ausschließt",
                "Bei Ansprüchen im Format der medizinischen Verwendung ist die therapeutische Wirksamkeit kein Merkmal des Anspruchs, sondern nur eine Frage der Ausführbarkeit"], 1,
               ["**Richtig ist die zweite Aussage.** Anspruchsmerkmale sind **im Lichte des gesamten Anspruchs** auszulegen, und derselbe Begriff hat innerhalb des Anspruchs grundsätzlich dieselbe Bedeutung, es sei denn, die Beschreibung oder die Funktion der Merkmale ergibt ein anderes Verständnis (EPG-BerG Hefei/Grundfos).",
                "Die erste Aussage ist falsch: Funktion **und** die vom Patent gelehrte körperliche und räumliche Anordnung eines Bauteils sind gemeinsam zu berücksichtigen (Dyson/Dreame). Die dritte ist falsch: Ob aus einem Unteranspruch Rückschlüsse zu ziehen sind, hängt vom Einzelfall ab; fügt er nur ein zusätzliches Merkmal hinzu, spricht das gerade **gegen** einen Umkehrschluss (Amgen/Regeneron). Die vierte ist falsch: Bei medizinischen Verwendungsansprüchen ist die objektive Eignung für die therapeutische Wirkung **inhärentes Merkmal** des Anspruchs (Amgen/Regeneron)."],
               level=3, concepts=["upc_auslegung_patentanspruch", "upc_fachperson"], norms=["Art. 25 EPGÜ"], cases=["upc_coa_hefei_grundfos_neues_vorbringen", "upc_coa_dyson_dreame_auslegung", "upc_coa_amgen_regeneron_auslegung"], step="step:upc_schema_verletzungsklage.2.1"),
        ]),
        dict(id="u04b", titel="Benutzungshandlungen: unmittelbar, mittelbar, äquivalent", einheiten=[
            intro("u04b-0", "Art. 25 und 26 EPGÜ und die Äquivalenz",
                  "Die Verletzungshandlungen stehen nicht im EPÜ, sondern im EPGÜ selbst: **Art. 25 EPGÜ** (unmittelbare Benutzung: Herstellen, Anbieten, Inverkehrbringen, Gebrauchen, Einführen, Besitzen eines Erzeugnisses; Anwenden oder Anbieten eines Verfahrens; Handlungen mit dem unmittelbaren Verfahrenserzeugnis) und **Art. 26 EPGÜ** (mittelbare Benutzung: Anbieten oder Liefern von Mitteln, die sich auf ein wesentliches Element der Erfindung beziehen, wenn der Dritte weiß oder es offensichtlich ist, dass sie zur Benutzung geeignet und bestimmt sind). Die Kataloge entsprechen §§ 9, 10 PatG, werden aber **autonom** ausgelegt: „Anbieten“ ist wirtschaftlich zu verstehen, die bloße invitatio ad offerendum genügt, Preisangabe und Lieferbereitschaft sind nicht nötig (Belkin/Philips); Anbieten und Inverkehrbringen sind selbständige Handlungen, Geoblocking der Kaufoption allein hilft nicht (Lepu/Occlutech); die Verwendungsbestimmung nach Art. 26 kann aus objektiven Umständen gefolgert werden (Onward/Niche). Räumlich gilt das Verbot im Gebiet aller Vertragsmitgliedstaaten, in denen das Patent Wirkung hat (Art. 34 EPGÜ). Für die **äquivalente** Verletzung enthält das EPGÜ keinen eigenen Test; Art. 2 des Protokolls zu Art. 69 EPÜ verlangt nur, gleichwertige Elemente zu berücksichtigen. Die Lokalkammer Den Haag hat einen vierstufigen Test angewandt (technische Gleichwertigkeit, angemessener Schutz, Rechtssicherheit und Erkennbarkeit für die Fachperson, keine Vorwegnahme durch den Stand der Technik); das Berufungsgericht hat sich noch nicht festgelegt. In der Klausur: Wortsinn zuerst, dann die deutschen Schneidmesser-Fragen und den Haager Test nebeneinander stellen.",
                  concepts=["upc_unmittelbare_verletzung", "upc_mittelbare_verletzung", "upc_aequivalenz"], norms=["Art. 25 EPGÜ", "Art. 26 EPGÜ", "Art. 34 EPGÜ"], cases=["upc_coa_belkin_philips_anbieten", "upc_coa_lepu_occlutech_vollstreckung", "upc_coa_onward_niche_mittelbar"]),
            fall("u04b-1", "Der Prototyp auf der Messe",
                 "Belkin zeigt auf einer Elektronikmesse in Berlin ein kabelloses Ladegerät, das nach Auffassung von Philips ein Patent für induktives Laden verletzt. Am Stand hängt kein Preisschild, Lieferbereitschaft besteht noch nicht, und das Personal erklärt Besuchern, es handle sich um eine Vorserie; Interessenten können aber ihre Kontaktdaten hinterlassen, um Angebote zu erhalten.",
                 "Liegt ein „Anbieten“ im Sinne des Art. 25 EPGÜ vor?", True,
                 ["**Ja!** „Anbieten“ in Art. 25 lit. a EPGÜ ist autonom und **wirtschaftlich** auszulegen, nicht als bindendes Vertragsangebot. Es genügt jede Handlung, die einen Gegenstand so präsentiert, dass Betrachter ein Angebot auf Überlassung abgeben können (invitatio ad offerendum). Preisangabe, Lieferbereitschaft oder Liefermöglichkeit sind **nicht** erforderlich (EPG-BerG Belkin/Philips).",
                  "Die Messepräsentation mit der Möglichkeit, Angebote anzufordern, präsentiert das Ladegerät als erwerbbaren Gegenstand. Dass es sich um eine Vorserie handelt, ändert nichts, solange der Gegenstand als solcher unter den Anspruch fällt. Belkin hat damit im Gebiet eines Vertragsmitgliedstaats angeboten; die Verletzungshandlung liegt vor."],
                 merke="Anbieten = wirtschaftlich: Präsentation genügt, Preis und Lieferbereitschaft sind egal (Belkin/Philips).",
                 level=1, concepts=["upc_anbieten", "upc_unmittelbare_verletzung"], norms=["Art. 25 EPGÜ"], cases=["upc_coa_belkin_philips_anbieten"], step="step:upc_schema_verletzungsklage.2.2"),
            fall("u04b-2", "Geoblocking statt Unterlassung",
                 "Lepu ist durch das EPG verurteilt worden, Herzverschlussimplantate in den Vertragsmitgliedstaaten weder anzubieten noch in Verkehr zu bringen. Lepu lässt die Produkte weiterhin mit Bildern und technischen Daten auf einer internationalen Verkaufsplattform präsentieren, sperrt aber die Kaufoption für Besucher aus dem EPG-Gebiet (Geoblocking). Occlutech beantragt die Festsetzung eines Zwangsgelds.",
                 "Genügt das Geoblocking der Kaufoption, um ein verbotenes Anbieten im EPG-Gebiet auszuschließen?", False,
                 ["**Nein!** Anbieten und Inverkehrbringen sind nach Art. 25 EPGÜ **selbständige Handlungen**. Wird beides verboten, reicht es nicht, nur den Kaufabschluss technisch zu sperren; die Präsentation der Produkte gegenüber Besuchern aus dem EPG-Gebiet bleibt ein Anbieten (EPG-BerG Lepu/Occlutech).",
                  "Der Adressat einer Unterlassungsanordnung muss zudem Dritte kontrollieren, denen er die Umsetzung überträgt: Wer eine Plattform nutzt und ihr Inhalte liefert, muss sicherstellen, dass diese Inhalte nicht gegen die Anordnung verstoßen. Ausreichen kann ein **zutreffender Disclaimer**, wenn kein Besucher den Inhalt vernünftigerweise als Angebot für die verbotenen Gebiete verstehen kann. Das bloße Geoblocking erfüllt diese Anforderung nicht; das Zwangsgeld nach Art. 63 Abs. 2, Art. 82 Abs. 4 EPGÜ, R. 354 VerfO kann festgesetzt werden."],
                 merke="Anbieten und Inverkehrbringen sind getrennt: Geoblocking sperrt den Kauf, nicht das Angebot (Lepu/Occlutech).",
                 level=2, concepts=["upc_anbieten", "upc_unterlassungsanordnung", "upc_vollstreckung"], norms=["Art. 25 EPGÜ", "Art. 63 EPGÜ", "R. 354 VerfO"], cases=["upc_coa_lepu_occlutech_vollstreckung"], step="step:upc_schema_verletzungsklage.2.2"),
            fall("u04b-3", "Das Implantat und die Verwendungsbestimmung",
                 "Onward vertreibt ein Rückenmarkstimulationssystem, das für sich genommen nicht alle Merkmale eines Verfahrensanspruchs von Niche verwirklicht. Die Klinik, die das System erwirbt, kann es aber nach der mitgelieferten Software und der Schulung nur in der patentgemäßen Weise einsetzen; Onward bewirbt genau diesen Einsatz. Niche stützt sich auf Art. 26 EPGÜ und trägt vor, die Bestimmung zur patentgemäßen Verwendung ergebe sich aus den Umständen.",
                 "Kann die Verwendungsbestimmung im Sinne des Art. 26 EPGÜ aus objektiven Umständen gefolgert werden?", True,
                 ["**Ja!** Art. 26 Abs. 1 EPGÜ verbietet das Anbieten oder Liefern von Mitteln, die sich auf ein wesentliches Element der Erfindung beziehen, wenn der Dritte weiß oder es offensichtlich ist, dass die Mittel dazu geeignet und **bestimmt** sind, für die Benutzung der Erfindung verwendet zu werden. Die Bestimmung ist ein Umstand in der Person des Belieferten, den der Lieferant regelmäßig nicht unmittelbar beweisen kann; sie kann deshalb aus **objektiven Umständen** gefolgert werden, die den hinreichend sicheren Schluss zulassen, dass das Mittel vom Belieferten erfindungsgemäß verwendet werden soll (EPG-BerG Onward/Niche).",
                  "Software, Schulung und Werbung, die nur den patentgemäßen Einsatz vorsehen, sind solche Umstände. Das System bezieht sich auf ein wesentliches Element der Erfindung, ist kein allgemein im Handel erhältliches Erzeugnis (Art. 26 Abs. 2 EPGÜ), und die Bestimmung ist für Onward offensichtlich. Die mittelbare Verletzung liegt vor; dass Onward das Patent in einer beschränkten, nicht eingetragenen Anspruchsfassung entgegengehalten wurde, war im Eilverfahren nicht von vornherein unzulässig."],
                 merke="Verwendungsbestimmung nach Art. 26 EPGÜ: aus objektiven Umständen erschließbar (Onward/Niche).",
                 level=2, concepts=["upc_mittelbare_verletzung"], norms=["Art. 26 EPGÜ", "Art. 26 Abs. 1 EPGÜ"], cases=["upc_coa_onward_niche_mittelbar"], step="step:upc_schema_verletzungsklage.2.2"),
        ]),
        dict(id="u04c", titel="Einwendungen und Haftung: Art. 27 bis 29, 63 EPGÜ, FRAND", einheiten=[
            intro("u04c-0", "Was der Beklagte noch einwenden kann",
                  "Nach Auslegung und Benutzungshandlung prüft das Gericht, ob die Handlung **im Gebiet** der Vertragsmitgliedstaaten und **ohne Zustimmung** erfolgte, und dann die Einwendungen. **Art. 27 EPGÜ** zählt die Beschränkungen der Wirkung auf, umfangreicher als § 11 PatG: private Handlungen (lit. a), Versuchshandlungen (lit. b), Züchtungsprivileg (lit. c), Bolar-Ausnahme für Zulassungsstudien (lit. d), Apothekenrezepturen (lit. e), fremde Schiffe und Luftfahrzeuge (lit. f, g), Landwirteprivileg (lit. i, j) und Dekompilierung von Software (lit. k, l). Wichtig für Art. 26: Wer nach lit. a bis c handelt, ist keine „berechtigte Person“ (Art. 26 Abs. 3 EPGÜ), Lieferungen an ihn können also mittelbare Verletzung sein. **Art. 28 EPGÜ** verweist das Vorbenutzungsrecht in das nationale Recht des jeweiligen Staates (in Deutschland § 12 PatG); es wirkt nur territorial. **Art. 29 EPGÜ** regelt die unionsweite, nicht die internationale Erschöpfung; berechtigte Gründe des Inhabers gegen den Weitervertrieb bleiben vorbehalten, die Beweislast für das Inverkehrbringen mit Zustimmung trägt der Beklagte (Art. 54 EPGÜ). Auf der Passivseite bestimmt **Art. 63 EPGÜ** i.V.m. Art. 25 autonom, wer „Verletzer“ ist: auch Anstifter, Mittäter und Gehilfen, aber der Geschäftsführer nicht schon kraft Organstellung (Belkin/Philips). Bei standardessentiellen Patenten kann der **FRAND-Einwand** aus Art. 102 AEUV den Unterlassungsanspruch sperren; die Lokalkammern Düsseldorf, Mannheim und München verlangen dafür einen lizenzwilligen Lizenzsucher (Dolby/Beko).",
                  concepts=["upc_beschraenkungen_wirkung", "upc_erschoepfung", "upc_verletzer"], norms=["Art. 27 EPGÜ", "Art. 28 EPGÜ", "Art. 29 EPGÜ", "Art. 63 EPGÜ"], cases=["upc_coa_belkin_philips_anbieten", "upc_cfi_dolby_beko_frand"],
                  distinctions=["d_upc_epg_deutsches_verfahren"]),
            fall("u04c-1", "Vorbenutzung in Deutschland, Lieferung nach Frankreich",
                 "Die Maschinenbau Roth GmbH hat ein Verfahren zum Härten von Zahnrädern seit 2019 in ihrem Werk in Hessen gewerblich benutzt. 2021 meldet ein Wettbewerber ein europäisches Patent mit einheitlicher Wirkung auf dasselbe Verfahren an. Roth beruft sich vor der Lokalkammer Düsseldorf auf ihr Vorbenutzungsrecht und meint, sie dürfe die gehärteten Zahnräder deshalb auch in Frankreich und Italien anbieten.",
                 "Wirkt das Vorbenutzungsrecht nach Art. 28 EPGÜ im gesamten Gebiet der Vertragsmitgliedstaaten?", False,
                 ["**Nein!** Nach Art. 28 EPGÜ hat, wer **in einem Vertragsmitgliedstaat** ein Vorbenutzungsrecht erworben hätte, wenn ein nationales Patent erteilt worden wäre, **in diesem Vertragsmitgliedstaat** dieselben Rechte auch gegenüber dem europäischen Patent. Das Vorbenutzungsrecht bleibt damit national und territorial begrenzt: Es richtet sich nach dem Recht des Staates, in dem es entstanden ist (hier § 12 PatG), und wirkt nur für dessen Gebiet.",
                  "Roth darf das Verfahren in Deutschland weiter benutzen und die Erzeugnisse dort anbieten. Anbieten und Inverkehrbringen in Frankreich und Italien sind dagegen Benutzungshandlungen nach Art. 25 EPGÜ ohne Rechtfertigung; auch Art. 29 EPGÜ hilft nicht, weil die Zahnräder nicht vom Patentinhaber oder mit seiner Zustimmung in Verkehr gebracht wurden. Für Klagen über das Vorbenutzungsrecht ist das EPG nach Art. 32 Abs. 1 lit. g EPGÜ zuständig."],
                 merke="Art. 28 EPGÜ: Vorbenutzung ist nationales Recht mit nationaler Reichweite.",
                 level=2, concepts=["upc_vorbenutzungsrecht", "upc_erschoepfung"], norms=["Art. 28 EPGÜ", "Art. 29 EPGÜ", "Art. 32 EPGÜ"], cases=[], step="step:upc_schema_verletzungsklage.2.5"),
            fall("u04c-2", "Der Geschäftsführer als Mitverletzer",
                 "Philips verklagt neben der Belkin GmbH auch deren Geschäftsführer persönlich auf Unterlassung. Philips trägt vor, der Geschäftsführer sei kraft seiner Organstellung für alle Vertriebsentscheidungen verantwortlich und hafte deshalb als Mittäter der Patentverletzung. Konkrete Kenntnis des Geschäftsführers vom Patent oder ein zweckgerichtetes Handeln ist nicht dargelegt.",
                 "Haftet der Geschäftsführer allein aufgrund seiner Organstellung als Verletzer im Sinne des Art. 63 EPGÜ?", False,
                 ["**Nein!** „Verletzer“ nach Art. 63 i.V.m. Art. 25 EPGÜ ist durch autonome Auslegung des EPGÜ zu bestimmen. Erfasst ist auch, wer die Benutzungshandlungen nicht selbst vornimmt, dem sie aber als **Anstifter, Mittäter oder Gehilfe** zuzurechnen sind. Die bloße Organstellung macht den Geschäftsführer aber nicht zum Mittäter; er haftet nur, wenn sein Handeln über berufstypische Pflichten hinausgeht, insbesondere wenn er das Unternehmen **zweckgerichtet** zur Verletzung nutzt oder **trotz Kenntnis** und Zumutbarkeit nicht einschreitet (EPG-BerG Belkin/Philips).",
                  "Kenntnis setzt voraus, dass der Geschäftsführer die Verletzung als solche erkennt oder sich ihr bewusst verschließt. Da Philips dazu nichts vorgetragen hat, ist die Klage gegen den Geschäftsführer unbegründet. Anders als bei Mittelspersonen (Art. 63 Abs. 1 Satz 2 EPGÜ, Art. 11 Satz 3 DurchsetzungsRL) gibt es gegen ihn keine Anordnung ohne eigene Zurechnung."],
                 merke="Geschäftsführer haftet nicht kraft Amtes, sondern nur bei zweckgerichtetem Handeln oder wissentlichem Nichteinschreiten (Belkin/Philips).",
                 level=2, concepts=["upc_verletzer", "upc_unterlassungsanordnung"], norms=["Art. 63 EPGÜ", "Art. 25 EPGÜ"], cases=["upc_coa_belkin_philips_anbieten"], step="step:upc_schema_verletzungsklage.1.2"),
            mc("u04c-3", "Der FRAND-Einwand vor dem EPG",
               "Dolby klagt aus einem standardessentiellen Patent für einen Audio-Codec gegen Beko, deren Smart-TVs ohne Lizenz nicht standardkompatibel wären. Beko beruft sich auf Art. 102 AEUV. Welche Aussage entspricht der Rechtsprechung der Lokalkammer Düsseldorf (Dolby/Beko)?",
               ["Das EPG darf den FRAND-Einwand nicht prüfen, weil kartellrechtliche Fragen nach Art. 32 Abs. 2 EPGÜ den nationalen Gerichten vorbehalten sind",
                "Eine marktbeherrschende Stellung scheidet aus, weil Verbraucher auf Fernseher mit anderen Codecs ausweichen könnten",
                "Der Unterlassungsanspruch ist nur gesperrt, wenn sich der Verletzer nach dem Verhandlungsprogramm des EuGH (Huawei/ZTE) als lizenzwilliger Lizenzsucher verhält; die Marktbeherrschung kann sich daraus ergeben, dass ohne Lizenz keine standardkompatiblen Produkte angeboten werden können",
                "Der Unterlassungsanspruch ist bei standardessentiellen Patenten stets ausgeschlossen; der Inhaber ist auf Schadensersatz beschränkt"], 2,
               ["**Richtig ist die dritte Aussage.** Die Lokalkammer Düsseldorf bejaht eine **marktbeherrschende Stellung** nach Art. 102 AEUV, wenn ohne Lizenz am Streitpatent keine mit einem gängigen Standard kompatiblen Produkte angeboten werden können; entscheidend ist die Verbrauchererwartung, dass alle gängigen Codecs unterstützt werden. Für das Verhandlungsprogramm nach Huawei/ZTE schließt sie sich den Lokalkammern Mannheim und München an: Der Unterlassungsanspruch aus Art. 63 EPGÜ ist nur gesperrt, wenn sich der Verletzer als **lizenzwilliger Lizenzsucher** verhält (LK Düsseldorf Dolby/Beko).",
                "Die erste Aussage ist falsch: Der FRAND-Einwand ist eine Einwendung gegen den Unterlassungsanspruch im Verletzungsverfahren, das EPG wendet Unionsrecht in vollem Umfang an (Art. 20, 24 EPGÜ). Die zweite verkennt die Verbrauchererwartung. Die vierte gibt es so nicht; Art. 63 EPGÜ räumt Ermessen ein, das regelmäßig zugunsten des Unterlassungsgebots ausgeübt wird."],
               level=3, concepts=["upc_unterlassungsanordnung", "upc_beschraenkungen_wirkung"], norms=["Art. 63 EPGÜ", "Art. 20 EPGÜ"], cases=["upc_cfi_dolby_beko_frand"], step="step:upc_schema_verletzungsklage.2.5"),
        ]),
    ],
)
